import numpy as np
import time


def _R(h):
    """Exact R for step heights h (non-negative)."""
    h = np.asarray(h, dtype=float)
    if h.size == 0 or not np.all(np.isfinite(h)):
        return -1.0
    s = h.sum()
    if s <= 0:
        return -1.0
    L = np.convolve(h, h)
    # ||f*f||_2^2 = sum (L_j^2 + L_j L_{j+1} + L_{j+1}^2)/3 over knots [0, L..., 0]
    Lp = np.concatenate(([0.0], L, [0.0]))
    a = Lp[:-1]
    b = Lp[1:]
    num = np.sum(a * a + a * b + b * b) / 3.0
    inf = Lp.max()
    # ||f*f||_1 = (sum h)^2
    return num / (s * s * inf)


def _make(a, p, N, x):
    u = np.abs(2.0 * x - 1.0)
    h = 1.0 - a * (u ** p)
    return np.maximum(h, 0.0)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = budget_seconds - 1.5  # margin

    N = 2001
    x = (np.arange(N) + 0.5) / N

    best_h = None
    best_R = -1.0

    if start is not None:
        s = np.asarray(start, dtype=float)
        rs = _R(s)
        if rs > best_R:
            best_R = rs
            best_h = s.copy()

    # Coarse 80x80 grid over a in [0,1.5], p in [0.25,12]
    a_vals = np.linspace(0.0, 1.5, 80)
    p_vals = np.linspace(0.25, 12.0, 80)

    best_a, best_p = 0.0, 2.0

    for a in a_vals:
        if time.process_time() - t0 > deadline * 0.6:
            break
        for p in p_vals:
            h = _make(a, p, N, x)
            r = _R(h)
            if r > best_R:
                best_R = r
                best_h = h
                best_a, best_p = a, p

    # Explicit p=1, p=2 checks
    for p in (1.0, 2.0):
        for a in a_vals:
            if time.process_time() - t0 > deadline * 0.7:
                break
            h = _make(a, p, N, x)
            r = _R(h)
            if r > best_R:
                best_R = r
                best_h = h
                best_a, best_p = a, p

    # Local refinement around best (a,p)
    def refine(a0, p0, da, dp, steps):
        nonlocal best_R, best_h, best_a, best_p
        for _ in range(steps):
            if time.process_time() - t0 > deadline:
                return
            improved = False
            for a in np.linspace(max(0.0, a0 - da), min(1.5, a0 + da), 9):
                for p in np.linspace(max(0.05, p0 - dp), min(20.0, p0 + dp), 9):
                    h = _make(a, p, N, x)
                    r = _R(h)
                    if r > best_R:
                        best_R = r
                        best_h = h
                        best_a, best_p = a, p
                        improved = True
            a0, p0 = best_a, best_p
            da *= 0.5
            dp *= 0.5
            if not improved and da < 1e-4 and dp < 1e-3:
                return

    refine(best_a, best_p, 0.1, 1.0, 40)

    # Golden-section style 1-D refinement alternating a and p
    def golden_1d(f, lo, hi, iters=40):
        gr = (np.sqrt(5.0) - 1.0) / 2.0
        c = hi - gr * (hi - lo)
        d = lo + gr * (hi - lo)
        fc = f(c)
        fd = f(d)
        for _ in range(iters):
            if fc > fd:
                hi, d, fd = d, c, fc
                c = hi - gr * (hi - lo)
                fc = f(c)
            else:
                lo, c, fc = c, d, fd
                d = lo + gr * (hi - lo)
                fd = f(d)
        return (lo + hi) / 2.0

    while time.process_time() - t0 < deadline:
        a0, p0 = best_a, best_p
        # refine a
        def fa(a):
            return _R(_make(a, p0, N, x))
        a_new = golden_1d(fa, max(0.0, a0 - 0.05), min(1.5, a0 + 0.05), 30)
        # refine p
        def fp(p):
            return _R(_make(a_new, p, N, x))
        p_new = golden_1d(fp, max(0.05, p0 - 0.5), min(20.0, p0 + 0.5), 30)
        h = _make(a_new, p_new, N, x)
        r = _R(h)
        if r > best_R:
            best_R = r
            best_h = h
            best_a, best_p = a_new, p_new
        else:
            # try a small local grid to escape
            improved = False
            for a in np.linspace(max(0.0, a0 - 0.02), min(1.5, a0 + 0.02), 5):
                for p in np.linspace(max(0.05, p0 - 0.2), min(20.0, p0 + 0.2), 5):
                    hh = _make(a, p, N, x)
                    rr = _R(hh)
                    if rr > best_R:
                        best_R = rr
                        best_h = hh
                        best_a, best_p = a, p
                        improved = True
            if not improved:
                break

    if best_h is None:
        return np.ones(50)
    return best_h

