def _score(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return 0.0
    L = np.convolve(h, h)
    m = L.max()
    num = np.sum(L[:-1] * L[:-1] + L[:-1] * L[1:] + L[1:] * L[1:]) / 3.0
    return num / (s * s * m)


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.90

    def elapsed():
        return time.process_time() - t0

    def norm(h):
        m = h.max()
        return h / m if m > 0 else h

    rng = np.random.default_rng(20240517)

    # Build a good starting shape, upsampled.
    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        s = np.maximum(s, 0.0)
        if s.size == 0 or s.sum() <= 0:
            s = np.ones(50)
    else:
        s = np.ones(50)

    N = min(200000, max(20000, s.size * 8))
    best = np.interp(np.linspace(0, 1, N), np.linspace(0, 1, s.size), s)
    best = norm(np.maximum(best, 1e-12))
    bestR = _score(best)

    # Score of a single-coordinate multiplicative change, evaluated fast.
    def try_mul(cur, curR, idx, fac, curL, curS):
        # recompute fully (simple + robust); N large but okay within budget
        cand = cur.copy()
        cand[idx] = max(cand[idx] * fac, 1e-12)
        cand = norm(cand)
        sc = _score(cand)
        return cand, sc

    # Phase A: coarse coordinate sweeps on the upsampled shape.
    def coord_sweep(cur, curR, step, tlimit, max_sweeps):
        sweeps = 0
        while time.process_time() < tlimit and sweeps < max_sweeps:
            sweeps += 1
            improved = False
            order = rng.permutation(cur.size)
            for idx in order:
                if time.process_time() >= tlimit:
                    break
                for fac in (1.0 + step, 1.0 / (1.0 + step)):
                    cand, sc = try_mul(cur, curR, idx, fac, None, None)
                    if sc > curR + 1e-15:
                        cur, curR = cand, sc
                        improved = True
                        break
            if not improved:
                step *= 0.6
                if step < 1e-6:
                    break
        return cur, curR, step

    best, bestR, _ = coord_sweep(best, bestR, 0.08,
                                 min(deadline, t0 + budget_seconds * 0.45), 60)

    # Phase B: block / window multiplicative moves to escape local optima,
    # using random windows and accepting improvements.
    step = 0.02
    no_improve = 0
    while time.process_time() < deadline:
        Nn = best.size
        improved = False
        # mix single-index and block moves
        if rng.random() < 0.5:
            idxs = [int(rng.integers(0, Nn))]
        else:
            L = int(rng.integers(2, max(3, Nn // 40)))
            i0 = int(rng.integers(0, Nn - L + 1))
            idxs = list(range(i0, i0 + L))
        for idx in idxs:
            if time.process_time() >= deadline:
                break
            for fac in (1.0 + step, 1.0 / (1.0 + step)):
                cand = best.copy()
                cand[idx] = max(cand[idx] * fac, 1e-12)
                cand = norm(cand)
                sc = _score(cand)
                if sc > bestR + 1e-15:
                    best, bestR = cand, sc
                    improved = True
                    break
        if improved:
            no_improve = 0
        else:
            no_improve += 1
            if no_improve > 3:
                step *= 0.75
                no_improve = 0
                if step < 1e-5:
                    step = 0.02

    print("R =", bestR, "N =", len(best), "cpu =", round(elapsed(), 2))
    return np.maximum(best, 0.0)

import numpy as np
import time
from scipy.optimize import minimize


def _score(h):
    h = np.asarray(h, dtype=float)
    if h.max() <= 0:
        return 0.0
    L = np.convolve(h, h)
    m = L.max()
    s = np.sum(L[:-1] * L[:-1] + L[:-1] * L[1:] + L[1:] * L[1:]) / 3.0
    l1 = (h.sum()) ** 2
    return s / (l1 * m)


def _convolve_grad(h, dR_dL):
    N = h.size
    c = np.convolve(dR_dL, h[::-1])
    return 2.0 * c[N - 1: N - 1 + N]


def _negRp_and_grad(x, p):
    h = np.exp(x - x.max())
    L = np.convolve(h, h)
    M = L.size
    Lmax = L.max()
    q = L / Lmax
    qp = np.power(q, p)
    mean_qp = np.mean(qp)
    mp = Lmax * mean_qp ** (1.0 / p)
    s = np.sum(L[:-1] * L[:-1] + L[:-1] * L[1:] + L[1:] * L[1:]) / 3.0
    l1 = (h.sum()) ** 2
    R = s / (l1 * mp)
    ds_dL = np.zeros(M)
    ds_dL[:-1] += (2.0 * L[:-1] + L[1:]) / 3.0
    ds_dL[1:] += (L[:-1] + 2.0 * L[1:]) / 3.0
    dmp_dL = (1.0 / M) * (mp / Lmax) ** (1.0 - p) * np.power(q, p - 1.0)
    dR_dL = ds_dL / (l1 * mp) - (s / (l1 * mp * mp)) * dmp_dL
    dR_dh = _convolve_grad(h, dR_dL)
    sh = h.sum()
    dR_dh -= (s / (l1 * l1 * mp)) * 2.0 * sh
    return -R, -(dR_dh * h)


def _lbfgsb_polish(h, p, deadline, maxiter=200):
    x0 = np.log(np.maximum(h, 1e-12))
    def fun(x):
        if time.process_time() >= deadline:
            raise StopIteration
        return _negRp_and_grad(x, p)
    try:
        res = minimize(fun, x0, jac=True, method='L-BFGS-B',
                       options={'maxiter': maxiter, 'maxfun': maxiter * 3,
                                'ftol': 1e-15, 'gtol': 1e-12})
        return np.exp(res.x - res.x.max())
    except StopIteration:
        return h


def _greedy_sweep(h, score, deadline, step, rng):
    N = h.size
    improved = False
    for idx in rng.permutation(N):
        if time.process_time() >= deadline:
            break
        for fac in (1.0 + step, 1.0 / (1.0 + step)):
            h2 = h.copy()
            h2[idx] = max(h2[idx] * fac, 1e-12)
            h2 /= h2.max()
            sc = _score(h2)
            if sc > score + 1e-15:
                h, score, improved = h2, sc, True
                break
    return h, score, improved


def _upsample(h, newN):
    N = h.size
    if newN % N == 0:
        h2 = np.repeat(h, newN // N)
    else:
        old_c = (np.arange(N) + 0.5) / N
        new_c = (np.arange(newN) + 0.5) / newN
        h2 = np.interp(new_c, old_c, h)
    h2 = np.maximum(h2, 1e-12)
    return h2 / h2.max()


def _continue(best, best_score, deadline, ps, rng, steps):
    for p in ps:
        if time.process_time() >= deadline:
            break
        cand = _lbfgsb_polish(best, p, deadline, maxiter=250)
        cand = np.maximum(cand, 1e-12); cand /= cand.max()
        sc = _score(cand)
        if sc > best_score:
            best, best_score = cand, sc
        for step in steps:
            if time.process_time() >= deadline:
                break
            best, best_score, _ = _greedy_sweep(best, best_score, deadline, step, rng)
    return best, best_score


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        best = np.maximum(np.asarray(start, dtype=float).copy(), 0.0)
        if best.size == 0 or best.max() <= 0:
            best = np.ones(200)
    else:
        best = np.ones(200)
    best = np.maximum(best, 1e-12); best /= best.max()
    best_score = _score(best)
    rng = np.random.default_rng(12345)
    N0 = best.size

    # Stage 1: refine at native resolution
    best, best_score = _continue(best, best_score, deadline,
        (60.0, 150.0, 300.0, 600.0, 1200.0, 3000.0, 10000.0),
        rng, (0.02, 0.01))

    # Stage 2: upsample to 2000 and refine (finer resolution -> better shape)
    if time.process_time() < deadline:
        target = max(2000, 2 * N0)
        if target <= 200000:
            best = _upsample(best, target)
            best_score = _score(best)
            best, best_score = _continue(best, best_score, deadline,
                (300.0, 600.0, 1200.0, 3000.0, 10000.0),
                rng, (0.01, 0.005))

    # Stage 3: further upsample if time remains
    if time.process_time() < t0 + 0.55 * (deadline - t0):
        target = 4000
        if target > best.size:
            best = _upsample(best, target)
            best_score = _score(best)
            best, best_score = _continue(best, best_score, deadline,
                (600.0, 1200.0, 3000.0, 10000.0),
                rng, (0.005, 0.002))

    # Final polish: very high p to sharpen ||f*f||_inf, then tiny greedy
    for p in (3000.0, 10000.0, 30000.0):
        if time.process_time() >= deadline:
            break
        cand = _lbfgsb_polish(best, p, deadline, maxiter=200)
        cand = np.maximum(cand, 1e-12); cand /= cand.max()
        sc = _score(cand)
        if sc > best_score:
            best, best_score = cand, sc
    for step in (0.003, 0.001):
        while time.process_time() < deadline:
            best, best_score, imp = _greedy_sweep(best, best_score, deadline, step, rng)
            if not imp:
                break

    return best

import numpy as np
import time
from scipy.optimize import minimize
from scipy.signal import fftconvolve


def _conv(a, b):
    a = np.asarray(a, dtype=float)
    b = np.asarray(b, dtype=float)
    if a.size >= 1024 or b.size >= 1024:
        return fftconvolve(a, b, mode='full')
    return np.convolve(a, b)


def _score(h):
    h = np.asarray(h, dtype=float)
    if h.max() <= 0:
        return 0.0
    L = _conv(h, h)
    m = L.max()
    s = np.sum(L[:-1] * L[:-1] + L[:-1] * L[1:] + L[1:] * L[1:]) / 3.0
    l1 = (h.sum()) ** 2
    return s / (l1 * m)


def _convolve_grad(h, dR_dL):
    N = h.size
    c = _conv(dR_dL, h[::-1])
    return 2.0 * c[N - 1: N - 1 + N]


def _make_fun_grad(p):
    def fg(x):
        h = np.exp(x - x.max())
        L = _conv(h, h)
        M = L.size
        Lmax = L.max()
        q = L / Lmax
        qp = np.power(q, p)
        mean_qp = np.mean(qp)
        mp = Lmax * mean_qp ** (1.0 / p)
        s = np.sum(L[:-1] * L[:-1] + L[:-1] * L[1:] + L[1:] * L[1:]) / 3.0
        l1 = (h.sum()) ** 2
        R = s / (l1 * mp)
        ds_dL = np.zeros(M)
        ds_dL[:-1] += (2.0 * L[:-1] + L[1:]) / 3.0
        ds_dL[1:] += (L[:-1] + 2.0 * L[1:]) / 3.0
        dmp_dL = (1.0 / M) * (mp / Lmax) ** (1.0 - p) * np.power(q, p - 1.0)
        dR_dL = ds_dL / (l1 * mp) - (s / (l1 * mp * mp)) * dmp_dL
        dR_dh = _convolve_grad(h, dR_dL)
        sh = h.sum()
        dR_dh -= (s / (l1 * l1 * mp)) * 2.0 * sh
        dR_dx = dR_dh * h
        return -R, -dR_dx
    return fg


def _lbfgsb_polish(h, p, deadline, maxiter=300):
    x0 = np.log(np.maximum(h, 1e-12))
    fg = _make_fun_grad(p)

    def fun(x):
        if time.process_time() >= deadline:
            raise StopIteration
        return fg(x)

    try:
        res = minimize(fun, x0, jac=True, method='L-BFGS-B',
                       options={'maxiter': maxiter, 'maxfun': maxiter * 3,
                                'ftol': 1e-15, 'gtol': 1e-12})
        h2 = np.exp(res.x - res.x.max())
        return h2
    except StopIteration:
        return h
    except Exception:
        return h


def _refine_support(h, deadline, rng, best_score):
    """Try shifting a window to allow support to expand/shrink at the edges."""
    N = h.size
    for _ in range(4):
        if time.process_time() >= deadline:
            break
        lead = 0
        tail = N - 1
        while lead < N and h[lead] < 1e-8 * h.max():
            lead += 1
        while tail > 0 and h[tail] < 1e-8 * h.max():
            tail -= 1
        if lead > 0 or tail < N - 1:
            # pad to allow expansion
            newh = np.concatenate([h[max(0, lead - 2):tail + 1]])
            if newh.size < N:
                pad = N - newh.size
                newh = np.concatenate([np.zeros(pad // 2), newh, np.zeros(pad - pad // 2)])
            newh = np.maximum(newh, 1e-12)
            newh /= newh.max()
            c = _lbfgsb_polish(newh, 2000.0, deadline, maxiter=120)
            c = np.maximum(c, 1e-12)
            c /= c.max()
            sc = _score(c)
            if sc > best_score:
                h, best_score = c, sc
            else:
                break
    return h, best_score


def _greedy_sweep(h, score, deadline, step, rng):
    N = h.size
    improved = False
    order = rng.permutation(N)
    for idx in order:
        if time.process_time() >= deadline:
            break
        for fac in (1.0 + step, 1.0 / (1.0 + step)):
            h2 = h.copy()
            h2[idx] *= fac
            if h2[idx] < 1e-12:
                h2[idx] = 1e-12
            h2 /= h2.max()
            sc = _score(h2)
            if sc > score + 1e-16:
                h = h2
                score = sc
                improved = True
                break
    return h, score, improved


def _upsample(h, newN):
    N = h.size
    if newN == N:
        return h.copy()
    if newN % N == 0:
        return np.repeat(h, newN // N)
    old_c = (np.arange(N) + 0.5) / N
    new_c = (np.arange(newN) + 0.5) / newN
    h2 = np.interp(new_c, old_c, h)
    h2 = np.maximum(h2, 1e-12)
    h2 /= h2.max()
    return h2


def construct(budget_seconds, start):
    t0 = time.process_time()
    deadline = t0 + budget_seconds * 0.93

    if start is not None:
        best = np.asarray(start, dtype=float).copy()
        best = np.maximum(best, 0.0)
        if best.size == 0 or best.max() <= 0:
            best = np.ones(400)
    else:
        best = np.ones(400)

    best = np.maximum(best, 1e-12)
    best /= best.max()
    best_score = _score(best)
    rng = np.random.default_rng(987654321)

    # Phase 1: polish at current resolution with several p values
    ps = (30.0, 60.0, 120.0, 250.0, 500.0, 1000.0, 2000.0, 4000.0, 8000.0, 16000.0)
    for p in ps:
        if time.process_time() >= deadline:
            break
        cand = _lbfgsb_polish(best, p, deadline, maxiter=200)
        cand = np.maximum(cand, 1e-12)
        cand /= cand.max()
        sc = _score(cand)
        if sc > best_score:
            best, best_score = cand, sc

    # Phase 2: upsampling - try doubling resolution if time allows and it helps
    # Only if current N is small enough and we have substantial time left
    while time.process_time() < deadline * 0.6 and best.size < 200000:
        newN = min(best.size * 2, 200000)
        if newN <= best.size:
            break
        cand = _upsample(best, newN)
        cand = _lbfgsb_polish(cand, 4000.0, deadline, maxiter=150)
        cand = np.maximum(cand, 1e-12)
        cand /= cand.max()
        sc = _score(cand)
        if sc > best_score + 1e-9:
            best, best_score = cand, sc
        else:
            break

    # Phase 3: greedy refinement
    for step in (0.01, 0.005, 0.002, 0.001):
        if time.process_time() >= deadline:
            break
        while time.process_time() < deadline:
            best, best_score, imp = _greedy_sweep(best, best_score, deadline, step, rng)
            if not imp:
                break

    # Phase 4: final polish with high p if time remains
    if time.process_time() < deadline:
        for p in (8000.0, 16000.0, 32000.0):
            if time.process_time() >= deadline:
                break
            cand = _lbfgsb_polish(best, p, deadline, maxiter=100)
            cand = np.maximum(cand, 1e-12)
            cand /= cand.max()
            sc = _score(cand)
            if sc > best_score:
                best, best_score = cand, sc

    return best

