def _convolve_grad(h, dR_dL):
    N = h.size
    c = _conv(dR_dL, h[::-1])
    return 2.0 * c[N - 1: N - 1 + N]


def _make_fg(p):
    def fg(x):
        h = np.exp(x - x.max())
        L = _conv(h, h)
        M = L.size
        Lmax = L.max()
        q = L / Lmax
        qp = np.power(q, p)
        mean_qp = np.mean(qp)
        mp = Lmax * mean_qp ** (1.0 / p)
        s = np.sum(L[:-1] * L[:-1] + L[:-1] * L[1:] + L[1:] * L[1:]) / 3.0
        l1 = (h.sum()) ** 2
        R = s / (l1 * mp)
        ds_dL = np.zeros(M)
        ds_dL[:-1] += (2.0 * L[:-1] + L[1:]) / 3.0
        ds_dL[1:] += (L[:-1] + 2.0 * L[1:]) / 3.0
        dmp_dL = (1.0 / M) * (mp / Lmax) ** (1.0 - p) * np.power(q, p - 1.0)
        dR_dL = ds_dL / (l1 * mp) - (s / (l1 * mp * mp)) * dmp_dL
        dR_dh = _convolve_grad(h, dR_dL)
        sh = h.sum()
        dR_dh -= (s / (l1 * l1 * mp)) * 2.0 * sh
        return -R, -(dR_dh * h)
    return fg


def _lbfgsb(h, p, deadline, maxiter=200):
    x0 = np.log(np.maximum(h, 1e-12))
    fg = _make_fg(p)

    def fun(x):
        if time.process_time() >= deadline:
            raise StopIteration
        return fg(x)

    try:
        res = minimize(fun, x0, jac=True, method='L-BFGS-B',
                       options={'maxiter': maxiter, 'maxfun': maxiter * 3,
                                'ftol': 1e-15, 'gtol': 1e-12})
        return np.exp(res.x - res.x.max())
    except (StopIteration, Exception):
        return h


def _upsample(h, newN):
    N = h.size
    if newN == N:
        return h.copy()
    if newN % N == 0:
        return np.repeat(h, newN // N)
    old_c = (np.arange(N) + 0.5) / N
    new_c = (np.arange(newN) + 0.5) / newN
    return np.interp(new_c, old_c, h)


def _greedy(h, score, deadline, step, rng):
    N = h.size
    improved = False
    order = rng.permutation(N)
    for idx in order:
        if time.process_time() >= deadline:
            break
        for fac in (1.0 + step, 1.0 / (1.0 + step)):
            h2 = h.copy()
            h2[idx] *= fac
            if h2[idx] < 1e-12:
                h2[idx] = 1e-12
            h2 /= h2.max()
            sc = _score(h2)
            if sc > score + 1e-15:
                h, score = h2, sc
                improved = True
                break
    return h, score, improved


def _polish(best, best_score, deadline, rng, ps):
    for p in ps:
        if time.process_time() >= deadline:
            break
        cand = _lbfgsb(best, p, deadline)
        cand = np.maximum(cand, 1e-12)
        cand /= cand.max()
        sc = _score(cand)
        if sc > best_score:
            best, best_score = cand, sc
    return best, best_score


def construct(budget_seconds, start):
    t0 = time.process_time()
    total = budget_seconds * 0.90
    deadline = t0 + total

    if start is not None:
        best = np.asarray(start, dtype=float).copy()
        best = best[best >= 0]
        if best.size == 0 or best.max() <= 0:
            best = np.ones(200)
    else:
        best = np.ones(200)

    best = np.maximum(best, 1e-12)
    best /= best.max()
    best_score = _score(best)
    rng = np.random.default_rng(12345)

    # Polish at current resolution with a range of p values.
    d1 = t0 + total * 0.20
    best, best_score = _polish(
        best, best_score, d1, rng, (30.0, 60.0, 120.0, 240.0, 480.0, 960.0))

    # Progressive upsampling: 2x, then 2x, then 2x, each with polish.
    for frac in (0.40, 0.65, 0.90):
        d = t0 + total * frac
        newN = min(best.size * 2, 200000)
        if newN > best.size:
            cand = _upsample(best, newN)
            cand = np.maximum(cand, 1e-12)
            cand /= cand.max()
            sc = _score(cand)
            if sc > best_score:
                best, best_score = cand, sc
        best, best_score = _polish(
            best, best_score, d, rng,
            (60.0, 120.0, 240.0, 480.0, 960.0, 1920.0))

    # Final fine polish at top resolution with greedy sweeps.
    for step in (0.02, 0.01, 0.005):
        if time.process_time() >= deadline:
            break
        while time.process_time() < deadline:
            best, best_score, imp = _greedy(best, best_score, deadline, step, rng)
            if not imp:
                break
    if time.process_time() < deadline:
        best, best_score = _polish(
            best, best_score, deadline, rng,
            (480.0, 960.0, 1920.0, 3840.0))

    return best
